def private(path):
 fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW);s=os.fstat(fd);assert stat.S_ISREG(s.st_mode)and s.st_uid==0 and stat.S_IMODE(s.st_mode)==0o600
 with os.fdopen(fd)as f:return json.load(f)
def save(name,value):
 fd=os.open(ROOT/name,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
 with os.fdopen(fd,'w')as f:json.dump(value,f,indent=2);f.flush();os.fsync(f.fileno())
 d=os.open(ROOT,os.O_RDONLY|os.O_DIRECTORY);os.fsync(d);os.close(d)
def append(value):
 path=ROOT/'ledger.jsonl';fd=os.open(path,os.O_RDWR|os.O_CREAT|os.O_APPEND|os.O_NOFOLLOW,0o600);fcntl.flock(fd,fcntl.LOCK_EX)
 with os.fdopen(os.dup(fd))as f:ordinal=sum(1 for _ in f)+1
 os.write(fd,(json.dumps({'physical_ordinal':ordinal,'wall':time.time(),'owner':OWNER,**value})+'\n').encode());os.fsync(fd);os.close(fd)
def aws(argv,label):
 
 try:p=subprocess.run(argv,capture_output=True,timeout=50)
 except subprocess.TimeoutExpired as e:
  save(label+'-timeout-'+str(time.time_ns())+'.json',{'timeout':True,'stdout':(e.stdout or b'').decode(),'stderr':(e.stderr or b'').decode()});raise AssertionError('Unknown AWS outcome retained; no retry')
 raw={'exit':p.returncode,'stdout':p.stdout.decode(),'stderr':p.stderr.decode()};save(label+'-raw-'+str(time.time_ns())+'.json',raw);assert p.returncode==0,'AWS refusal: private raw receipt retained; no dependent mutations';return json.loads(p.stdout)if p.stdout.strip()else{}
def read(action,args=[]):return aws(['aws','--region','eu-central-1','--output','json','--no-cli-pager','ec2',action,*args],'read-'+action)
def foreign_tgw():
 rows=read('describe-transit-gateway-route-tables')['TransitGatewayRouteTables'];result=[]
 for r in rows:
  if known_owner(r,'TransitGatewayRouteTableId',recorded_ids()):
   assert recorded_ids()[r['TransitGatewayRouteTableId']]=='tgw-table';continue
  rid=r['TransitGatewayRouteTableId'];result.append({'id':rid,'associations':sorted(read('get-transit-gateway-route-table-associations',['--transit-gateway-route-table-id',rid])['Associations'],key=lambda x:x['TransitGatewayAttachmentId']),'propagations':sorted(read('get-transit-gateway-route-table-propagations',['--transit-gateway-route-table-id',rid])['TransitGatewayRouteTablePropagations'],key=lambda x:x['TransitGatewayAttachmentId'])})
 return sorted(result,key=lambda x:x['id'])
VPN_INVENTORY_QUERY='VpnConnections[].{VpnConnectionId:VpnConnectionId,Tags:Tags,InsideCidrs:Options.TunnelOptions[].TunnelInsideCidr}'
def known_owner(value,id_key,recorded):
 owned=any(t.get('Key')=='TunnexLab'and t.get('Value')==OWNER for t in value.get('Tags',[]))
 if owned:assert value[id_key]in recorded,'Unknown OWNER-tag resource: preserve inventory and reconcile exact durable intent, never skip or adopt'
 return owned
def recorded_ids():
 records={}
 for role,(_,path)in RESULTS.items():
  file=ROOT/(role+'-result.json')
  if file.exists():
   value=private(file)
   for key in path:value=value[key]
   records[value]=role
 return records
def preflight():
 recorded=recorded_ids()
 # Key-free inventory only. Unknown owned objects never become implicit authority.
 inventory=[('describe-vpcs','Vpcs','VpcId'),('describe-customer-gateways','CustomerGateways','CustomerGatewayId'),('describe-transit-gateways','TransitGateways','TransitGatewayId'),('describe-key-pairs','KeyPairs','KeyPairId'),('describe-subnets','Subnets','SubnetId'),('describe-network-interfaces','NetworkInterfaces','NetworkInterfaceId'),('describe-vpn-gateways','VpnGateways','VpnGatewayId'),('describe-internet-gateways','InternetGateways','InternetGatewayId'),('describe-route-tables','RouteTables','RouteTableId'),('describe-security-groups','SecurityGroups','GroupId'),('describe-transit-gateway-vpc-attachments','TransitGatewayVpcAttachments','TransitGatewayAttachmentId')]
 for action,key,idkey in inventory:
  rows=read(action)[key]
  for row in rows:
   ours=known_owner(row,idkey,recorded)
   if ours and action=='describe-vpcs':assert recorded[row[idkey]]=='vpc' and row['CidrBlock']=='10.87.0.0/16'
   if ours and action=='describe-customer-gateways':assert row['IpAddress']=='13.63.169.255' and str(row['BgpAsn'])=='65000'
   if ours and action=='describe-transit-gateways':
    o=row['Options'];assert o['AmazonSideAsn']==64512 and o['DefaultRouteTableAssociation']==o['DefaultRouteTablePropagation']==o['VpnEcmpSupport']=='disable'
   if action=='describe-vpcs' and not ours:
    for c in row['CidrBlockAssociationSet']:assert not ipaddress.ip_network(c['CidrBlock']).overlaps(ipaddress.ip_network('10.87.0.0/16'))
 for row in read('describe-vpn-connections',['--query',VPN_INVENTORY_QUERY]):
  ours=known_owner(row,'VpnConnectionId',recorded)
  if not ours:assert not set(row.get('InsideCidrs')or[]).intersection({'169.254.124.0/30','169.254.124.4/30','169.254.124.8/30','169.254.124.12/30'})
 instances=read('describe-instances',['--filters','Name=instance-state-name,Values=pending,running'])['Reservations']
